(39909, 'Leviticus 15:6', 'Leviticus', 15, 6, 'یا په هغه شي باندې کښېني چې هغه سړی ورباندې ناست ؤ، نو هغه کس باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'یا په هغه شی باندې کشېنی چې هغه سری ورباندې ناست و، نو هغه کس باید خپل کالی ووینجی او غسل دې وکری، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39910, 'Leviticus 15:7', 'Leviticus', 15, 7, 'هرڅوک چې د هغه سړي سره ولګیږي، باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'هرچوک چې د هغه سری سره ولګیزی، باید خپل کالی ووینجی او غسل دې وکری، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(39911, 'Leviticus 15:8', 'Leviticus', 15, 8, 'که چېرې هغه کس چې زوه ورڅخه راوځي په داسې یو کس باندې چې هغه پاک وي لیاړې واچوي، هغه سړی باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'که چېرې هغه کس چې زوه ورچخه راوجی په داسې یو کس باندې چې هغه پاک وی لیارې واچوی، هغه سری باید خپل کالی ووینجی او غسل دې وکری، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39912, 'Leviticus 15:9', 'Leviticus', 15, 9, 'که دا سړی په کوم زین باندې کښېني، هغه به ناپاک شي', 'که دا سری په کوم زین باندې کشېنی، هغه به ناپاک شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39913, 'Leviticus 15:10', 'Leviticus', 15, 10, 'او هرڅوک چې د هغه شي سره ولګیږي چې دا سړی ورباندې ناست ؤ، هغه به تر ماښامه پورې ناپاک وي. هرڅوک چې داسې شیان راپورته کړي، هغه باید خپل کالي ووینځي او غسل دې وکړي، خو تر ماښامه پورې به ناپاک پاتې شي.', 'او هرچوک چې د هغه شی سره ولګیزی چې دا سری ورباندې ناست و، هغه به تر ماشامه پورې ناپاک وی. هرچوک چې داسې شیان راپورته کری، هغه باید خپل کالی ووینجی او غسل دې وکری، خو تر ماشامه پورې به ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39914, 'Leviticus 15:11', 'Leviticus', 15, 11, 'که چېرې یو سړی چې زوه ورڅخه راووځي او خپل لاسونه یې نه وي وینځلي، په کوم بل کس باندې ولګیږي، نو هغه څوک چې دی ورسره لګېدلی دی باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'که چېرې یو سری چې زوه ورچخه راووجی او خپل لاسونه یې نه وی وینجلی، په کوم بل کس باندې ولګیزی، نو هغه چوک چې دی ورسره لګېدلی دی باید خپل کالی ووینجی او غسل دې وکری، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39915, 'Leviticus 15:12', 'Leviticus', 15, 12, 'که هغه سړی چې زوه ورڅخه راوځي د خټو هر لوښي ته لاس وروړي، هغه باید مات شي او که د لرګي کوم لوښي ته لاس وروړي، هغه باید ووینځل شي.', 'که هغه سری چې زوه ورچخه راوجی د ختو هر لوشی ته لاس وروری، هغه باید مات شی او که د لرګی کوم لوشی ته لاس وروری، هغه باید ووینجل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(39916, 'Leviticus 15:13', 'Leviticus', 15, 13, 'له هغې وروسته چې د زوې د راوتلو څخه د دغه سړي علاج وشي، هغه باید اووه ورځې صبر وکړي او بیا دې د چینې په تازه اوبو کې خپل کالي ووینځي او غسل دې وکړي، نو هغه به پاک شي.', 'له هغې وروسته چې د زوې د راوتلو چخه د دغه سری علاج وشی، هغه باید اووه ورجې صبر وکری او بیا دې د چینې په تازه اوبو کې خپل کالی ووینجی او غسل دې وکری، نو هغه به پاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(39917, 'Leviticus 15:14', 'Leviticus', 15, 14, 'هغه باید په اتمه ورځ دوه کوترې یا دوه قمري ګانې واخلي او د څښتن حضور ته دې د سپېڅلې خېمې د دروازې خولې ته راشي او هغه دې کاهن ته ورکړي.', 'هغه باید په اتمه ورج دوه کوترې یا دوه قمری ګانې واخلی او د چشتن حضور ته دې د سپېچلې خېمې د دروازې خولې ته راشی او هغه دې کاهن ته ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(39918, 'Leviticus 15:15', 'Leviticus', 15, 15, 'کاهن دې هغه قرباني کړي، یوه د ګناه د نذرانې دپاره او بله د سوځېدونکې نذرانې دپاره. په دې ډول به کاهن د څښتن په حضور کې د هغه سړي دپاره د هغه د زوې د راوتلو له امله کفاره ادا کړي.', 'کاهن دې هغه قربانی کری، یوه د ګناه د نذرانې دپاره او بله د سوجېدونکې نذرانې دپاره. په دې دول به کاهن د چشتن په حضور کې د هغه سری دپاره د هغه د زوې د راوتلو له امله کفاره ادا کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39919, 'Leviticus 15:16', 'Leviticus', 15, 16, 'کله چې له یو سړي څخه مني راووځي، هغه باید خپل ټول ځان ووینځي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'کله چې له یو سری چخه منی راووجی، هغه باید خپل تول جان ووینجی، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39920, 'Leviticus 15:17', 'Leviticus', 15, 17, 'هر هغه شی چې د ټوکر یا څرمنې څخه جوړ شوی وي او مني ورباندې لوېدلي وي باید ووینځل شي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', 'هر هغه شی چې د توکر یا چرمنې چخه جور شوی وی او منی ورباندې لوېدلی وی باید ووینجل شی، خو هغه به تر ماشامه پورې ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39921, 'Leviticus 15:18', 'Leviticus', 15, 18, 'سړی او ښځه دواړه باید د یوځای کېدلو څخه وروسته غسل وکړي، خو تر ماښامه پورې به ناپاک پاتې شي.', 'سری او شجه دواره باید د یوجای کېدلو چخه وروسته غسل وکری، خو تر ماشامه پورې به ناپاک پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39922, 'Leviticus 15:19', 'Leviticus', 15, 19, 'کله چې یوه ښځه میاشتینۍ ناروغي ولري، هغه اووه ورځې ناپاکه پاتې کیږي. هرڅوک چې دې ښځې ته لاس وروړي، هغه به تر ماښامه پورې ناپاک وي.', 'کله چې یوه شجه میاشتینی ناروغی ولری، هغه اووه ورجې ناپاکه پاتې کیزی. هرچوک چې دې شجې ته لاس وروری، هغه به تر ماشامه پورې ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39923, 'Leviticus 15:20', 'Leviticus', 15, 20, 'که هغه د خپلې میاشتینۍ ناروغۍ په وخت کې په هر شي باندې کښېني یا ورباندې څملي، هغه شی به ناپاک شي.', 'که هغه د خپلې میاشتینی ناروغی په وخت کې په هر شی باندې کشېنی یا ورباندې چملی، هغه شی به ناپاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39924, 'Leviticus 15:24', 'Leviticus', 15, 24, 'که چېرې یو سړی د هغې ښځې سره په هغه وخت کې یوځای شي کله چې د هغې میاشتینۍ ناروغي پیل کیږي، هغه سړی به اووه ورځې ناپاک وي. په هرې بسترې باندې چې هغه څملي هغه بستره به ناپاکه شي.', 'که چېرې یو سری د هغې شجې سره په هغه وخت کې یوجای شی کله چې د هغې میاشتینی ناروغی پیل کیزی، هغه سری به اووه ورجې ناپاک وی. په هرې بسترې باندې چې هغه چملی هغه بستره به ناپاکه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(39925, 'Leviticus 15:25', 'Leviticus', 15, 25, 'که چېرې د یوې ښځې څخه د میاشتینۍ ناروغۍ څخه پرته د ډېرو ورځو دپاره وینه بهیږي، یا برسېره په عادي میاشتینۍ ناروغۍ د هغې څخه وینه بهیږي، نو ترڅو پورې چې دا وینه بهیږي، هغه ښځه د میاشتینۍ ناروغۍ په شان ناپاکه پاتې کیږي.', 'که چېرې د یوې شجې چخه د میاشتینی ناروغی چخه پرته د دېرو ورجو دپاره وینه بهیزی، یا برسېره په عادی میاشتینی ناروغی د هغې چخه وینه بهیزی، نو ترچو پورې چې دا وینه بهیزی، هغه شجه د میاشتینی ناروغی په شان ناپاکه پاتې کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_15_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
